"""POST /catalog/medications/match generated by the app agrees with api_contract (4.13)."""

import json
from pathlib import Path

import pytest

from drugtime.main import create_app

CONTRACT = Path(__file__).resolve().parents[3] / "api_contract" / "openapi.json"
PATH, METHOD = "/catalog/medications/match", "post"
pytestmark = pytest.mark.skipif(not CONTRACT.exists(), reason="api_contract chưa checkout")


@pytest.fixture(scope="module")
def specs():
    return create_app().openapi(), json.loads(CONTRACT.read_text(encoding="utf-8"))


def _resolve(spec, node):
    while "$ref" in node:
        node_path = node["$ref"].removeprefix("#/").split("/")
        node = spec
        for part in node_path:
            node = node[part]
    return node


def _branches(spec, node):
    node = _resolve(spec, node)
    if "anyOf" in node:
        return [b for branch in node["anyOf"] for b in _branches(spec, branch)]
    if isinstance(node.get("type"), list):
        return [{**node, "type": t} for t in node["type"]]
    return [node]


def _shape(spec, node):
    """Comparable facts of a schema: types, bounds, pattern, enum, nested object shape."""
    shapes = []
    for branch in _branches(spec, node):
        shape = {"type": branch.get("type")}
        if shape["type"] == "null":
            # `type: [string, null]` keeps string keywords on the node; they do not apply here.
            shapes.append(shape)
            continue
        for key in ("minLength", "maxLength", "pattern", "maxItems", "enum"):
            if key in branch:
                shape[key] = branch[key]
        for key in ("minimum", "maximum"):
            if key in branch:
                shape[key] = float(branch[key])
        if branch.get("type") == "object":
            shape["required"] = sorted(branch.get("required", []))
            shape["additionalProperties"] = branch.get("additionalProperties")
            shape["properties"] = {
                k: _shape(spec, v) for k, v in sorted(branch.get("properties", {}).items())
            }
        if branch.get("type") == "array":
            shape["items"] = _shape(spec, branch["items"])
        shapes.append(shape)
    return sorted(shapes, key=repr)


def test_match_operation_matches_contract(specs):
    actual, expected = (s["paths"][PATH][METHOD] for s in specs)
    assert actual["operationId"] == expected["operationId"] == "matchCatalogMedicationsFromOcr"
    assert actual["tags"] == expected["tags"] == ["catalog"]
    assert actual["security"] == expected["security"] == [{"bearerAuth": []}]
    assert set(actual["responses"]) == set(expected["responses"]) == {"200", "401", "422", "500"}
    for code in ("200", "422", "500"):
        header = actual["responses"][code]["headers"]["Cache-Control"]
        assert header["schema"]["const"] == "no-store"


@pytest.mark.parametrize("where", ["request", "200"])
def test_match_schemas_match_contract(specs, where):
    def schema(spec):
        op = spec["paths"][PATH][METHOD]
        if where == "request":
            return op["requestBody"]["content"]["application/json"]["schema"]
        return op["responses"]["200"]["content"]["application/json"]["schema"]

    actual, expected = specs
    assert _shape(actual, schema(actual)) == _shape(expected, schema(expected))


def test_request_limit_default_equals_configured_default(specs):
    _, expected = specs
    request = _resolve(expected, {"$ref": "#/components/schemas/OcrMatchRequest"})
    from drugtime.shared.config import Settings

    configured = Settings(_env_file=None).ocr_match_default_limit
    assert request["properties"]["limit"]["default"] == configured
